import { Link } from "react-router-dom";
import { FaSearch, FaShoppingCart } from "react-icons/fa";
import logo from "../assets/logo.jpg"; // Kiểm tra lại đường dẫn logo
import "./Menu.css";

const Menu = () => {
    return (
        <nav className="menu">
            <ul className="menu-list">
                <li className="menu-item">
                    <Link to="/home" className="logo-link">
                        <img src={logo} alt="Logo" />
                    </Link>
                </li>
                <li className="menu-item"><Link to="/about-us">Về chúng tôi</Link></li>
                <li className="menu-item"><Link to="/blog">Blog</Link></li>
                <li className="menu-item"><Link to="/men">Đồ nam</Link></li>
                <li className="menu-item"><Link to="/women">Đồ nữ</Link></li>
                <li className="menu-item"><Link to="/kids">Trẻ em</Link></li>
                <li className="menu-item"><Link to="/new-arrivals">Hàng mới về</Link></li>

                {/* Ô tìm kiếm */}
                <li className="menu-item search">
                    <div className="search-wrapper">
                        <input type="text" placeholder="Tìm kiếm..." />
                        <button className="search-button">
                            <FaSearch className="search-icon" />
                        </button>
                    </div>
                </li>

                {/* Nút đăng nhập và đăng ký */}
                <li className="menu-item"><Link to="/login" className="auth-button">Đăng nhập</Link></li>
                <li className="menu-item"><Link to="/register" className="auth-button">Đăng ký</Link></li>

                {/* Giỏ hàng */}
                <li className="menu-item">
                    <Link to="/giohang" className="cart-button">
                        <FaShoppingCart className="cart-icon" />
                        <span className="cart-text">Giỏ hàng</span>
                    </Link>
                </li>
            </ul>
        </nav>
    );
};

export default Menu;
